const input = $input.first().json || {};
const question = (input.question || '').toString().trim();

return [{
  json: {
    question: question || 'Resumen general de leads y deals activos'
  }
}];

const response = $input.first().json;
const userQuestion = $('Normalizar Pregunta').first().json.question;

let text = '';
try {
  text = response.candidates[0].content.parts[0].text;
} catch(e) {
  text = '{"is_mutation": false, "table": "leads", "query_params": "select=id,full_name,status&limit=10"}';
}

const cleaned = text.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { is_mutation: false, table: 'leads', query_params: 'select=id,full_name,status&limit=10' };
}

if (parsed.is_mutation) {
  return [{
    json: {
      skip_fetch: true,
      question: userQuestion,
      refusal_message: parsed.refusal || 'No se pueden realizar modificaciones de datos desde la consulta conversacional. Por favor utiliza la interfaz del CRM.'
    }
  }];
}

const allowedTables = ['leads', 'deals', 'companies'];
const table = allowedTables.includes(parsed.table) ? parsed.table : 'leads';
let queryParams = parsed.query_params || 'select=*&limit=20';

// Schema de columnas válidas por tabla
const tableSchemas = {
  leads: ['id', 'full_name', 'email', 'phone', 'source', 'status', 'company_id', 'created_at', 'ai_score', 'ai_category', 'ai_summary', 'ai_next_step', 'ai_analyzed_at', 'notes'],
  deals: ['id', 'title', 'value', 'stage', 'probability', 'expected_close', 'stalled', 'lead_id', 'company_id', 'created_at', 'updated_at', 'ai_risk_score', 'ai_risk_factors', 'ai_analyzed_at'],
  companies: ['id', 'name', 'industry', 'website', 'owner_id', 'created_at']
};

// Sanitización y corrección según la tabla seleccionada
if (table === 'leads') {
  queryParams = queryParams
    .replace(/\bstage\b/g, 'status')
    .replace(/\bname\b/g, 'full_name')
    .replace(/\bamount\b/g, 'value');
} else if (table === 'deals') {
  queryParams = queryParams
    .replace(/\bstatus\b/g, 'stage')
    .replace(/\bname\b/g, 'title')
    .replace(/\bamount\b/g, 'value');
} else if (table === 'companies') {
  queryParams = queryParams
    .replace(/\bfull_name\b/g, 'name')
    .replace(/\btitle\b/g, 'name');
}

// Validar que las columnas solicitadas en select= pertenezcan a la tabla
const validColumns = tableSchemas[table];
const selectMatch = queryParams.match(/select=([^&]+)/);
if (selectMatch && selectMatch[1] && selectMatch[1] !== '*') {
  const requestedCols = selectMatch[1].split(',').map(c => c.trim());
  const filteredCols = requestedCols.filter(col => validColumns.includes(col));
  if (filteredCols.length === 0) {
    const defaultCol = table === 'leads' ? 'id,full_name,status' : table === 'deals' ? 'id,title,stage,value' : 'id,name';
    queryParams = queryParams.replace(/select=[^&]+/, `select=${defaultCol}`);
  } else {
    queryParams = queryParams.replace(/select=[^&]+/, `select=${filteredCols.join(',')}`);
  }
}

return [{
  json: {
    skip_fetch: false,
    question: userQuestion,
    table,
    query_params: queryParams
  }
}];

