const response = $input.first().json;
const rawData = $('Consultar Supabase (GET Only)').first().json;

let text = '';
try {
  text = response.candidates[0].content.parts[0].text;
} catch(e) {
  text = 'Se encontraron ' + (Array.isArray(rawData) ? rawData.length : 1) + ' registros en la consulta.';
}

const sanitized = text
  .replace(/```markdown\n?/gi, '')
  .replace(/```json\n?/gi, '')
  .replace(/```\n?/g, '')
  .trim();

return [{
  json: {
    answer_text: sanitized,
    raw_data: rawData
  }
}];
